import{_ as e,o as l,c as o,ai as i}from"./chunks/framework.DAbPic9L.js";const u=JSON.parse('{"title":"理解编程","description":"","frontmatter":{},"headers":[],"relativePath":"foundation/understand-program.md","filePath":"foundation/understand-program.md","lastUpdated":1787215730000}'),t={name:"foundation/understand-program.md"};function r(d,a,n,c,p,s){return l(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="理解编程" tabindex="-1">理解编程 <a class="header-anchor" href="#理解编程" aria-label="Permalink to &quot;理解编程&quot;">​</a></h1><p>文/晨风不可依米</p><br><h2 id="理解现实事物与抽象概括" tabindex="-1">理解现实事物与抽象概括 <a class="header-anchor" href="#理解现实事物与抽象概括" aria-label="Permalink to &quot;理解现实事物与抽象概括&quot;">​</a></h2><p>万物皆对象。现实事物与抽象概括的映射关系，本质上是现实事物所具有的特点和运动，可归结为抽象事物的属性和行为。</p><p>比如，一个人类具有身高、体重、性别、年龄等特点，同时也具有行走、吃饭、睡觉等行为。这些特点和行为，就是人类所具有属性和行为的抽象概括。</p><h2 id="编程的本质-数据和函数" tabindex="-1">编程的本质：数据和函数 <a class="header-anchor" href="#编程的本质-数据和函数" aria-label="Permalink to &quot;编程的本质：数据和函数&quot;">​</a></h2><p><span class="text-red">编程的本质是数据和函数的组合</span>。 数据是现实世界中事物的抽象概括和映射，可通过现实事物理解数据模型；函数则是对行为流程的逻辑判断和数据运算；可通过输入参数、逻辑判断和数据运算，以及返回结果来理解函数的流程内容。</p><h2 id="编程的核心思维" tabindex="-1">编程的核心思维 <a class="header-anchor" href="#编程的核心思维" aria-label="Permalink to &quot;编程的核心思维&quot;">​</a></h2><ul><li>分解思维：将整体问题分解为多个小问题，逐步解决。</li><li>抽象思维：忽略细节，保留核心特征，抽象概括问题。</li><li>模式识别：重复结构，统一处理，可提取为逻辑函数。</li><li>算法思维：通过有限步骤逻辑判断和数据运算，简洁快速解决问题。</li></ul><h2 id="编程的基本概念" tabindex="-1">编程的基本概念 <a class="header-anchor" href="#编程的基本概念" aria-label="Permalink to &quot;编程的基本概念&quot;">​</a></h2><ul><li><p>主线任务：用户活动中切身想要完成的事物（价值类型：功能实用与精神消耗）。</p><ul><li>功能实用：完成主线任务所提效的必要工具（省时省力省钱方便）。</li><li>精神消耗：完成主线任务所满足的情感表达（大多体现在分享欲）。</li></ul></li><li><p>用户需求：围绕在主线任务过程中所产生的必要条件（诉求、期待、满足感）。</p></li><li><p>市场痛点：围绕在主线任务过程中所遭遇的过程难题（问题、障碍、关卡点）。</p></li><li><p>理解业务：基于用户需求和市场痛点，通过建立一套“业务目标、业务规则、业务流程”方案，以帮助用户完成主线任务。而业务的核心，在于业务目标所决定的一系列业务规则；而这些规则通常通过生命周期状态，来明确在不同阶段能做什么、不能做什么，从而界定业务的目标与边界。</p></li><li><p>理解技术：在明确业务目标与业务约束的前提下，围绕业务需求构建可落地的技术解决方案；重点关注技术方案的可行性、以及在性能、稳定性、扩展性和成本等下如何实现。另特别注意，数据结构、常见算法、设计模式是技术实现的底层基础。</p></li></ul><h2 id="编程的开发概念" tabindex="-1">编程的开发概念 <a class="header-anchor" href="#编程的开发概念" aria-label="Permalink to &quot;编程的开发概念&quot;">​</a></h2><ul><li><p>平台: 基于物理设备类型的叫法；比如<code>PC端</code>、<code>Mobile端</code>、<code>Tablt端</code>等。</p></li><li><p>载体: 基于软件运行环境的叫法: 比如<code>Web端</code>、<code>H5端</code>、<code>App端</code>、<code>桌面端</code>、<code>小程序端</code>等。</p></li></ul>',14)])])}const _=e(t,[["render",r]]);export{u as __pageData,_ as default};
